if ($action == 'storno') {
    // stornovat lze cokoliv krome dorucenych (2017: i odeslane, kdyz se balik vrati)
    $before = $db->query("SELECT id, status FROM orders WHERE id IN (" . $idList . ")");
    $n = 0;
    foreach ($before as $b) {
        if ($b['status'] != 'delivered') {
            try {
                legacy_command(new \App\Ordering\Application\Command\CancelOrder(
                    \App\Ordering\Domain\ValueObject\OrderId::fromString($b['id']),
                    ''
                ));
                $n++;
                audit_log('order', $b['id'], 'storno', array('from' => $b['status'], 'bulk' => true));
            } catch (\App\Ordering\Domain\Exception\InvalidOrderStateTransitionException) {
                // Ignoruj objednávky, které nemohou být zrušeny (např. již odesláno).
            }
        }
    }
    flash('Stornováno objednávek: ' . $n);

